dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ бит_ЛицевыеСчета.Ссылка КАК ЛицевойСчет, бит_ЛицевыеСчета.ИдентификаторЖКУ КАК ИдентификаторЖКУ ПОМЕСТИТЬ ВТ_ЛицевыеСчетаОбщая ИЗ Справочник.бит_ЛицевыеСчета КАК бит_ЛицевыеСчета ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_СписокЗданий КАК бит_СписокЗданий ПО бит_ЛицевыеСчета.Здание = бит_СписокЗданий.Ссылка ГДЕ бит_ЛицевыеСчета.Архивный = ЛОЖЬ И НЕ бит_ЛицевыеСчета.ПометкаУдаления И НЕ бит_СписокЗданий.ПометкаУдаления {ГДЕ (бит_ЛицевыеСчета.Ссылка В (&СписокЛС)), (бит_ЛицевыеСчета.Организация = &ОтборОрганизация), (бит_СписокЗданий.Улица В (&СписокУлиц)), (бит_ЛицевыеСчета.Здание В (&СписокЗданий)), (ВЫБОР КОГДА &ТипДомаГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ТОГДА бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ИЛИ бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.ПустаяСсылка) ИНАЧЕ бит_СписокЗданий.ТипыДомовГИСЖКХ В (&ТипДомаГИСЖКХ) КОНЕЦ)}
ИНДЕКСИРОВАТЬ ПО ЛицевойСчет ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ бит_ЛицевыеСчета.Ссылка КАК ЛицевойСчет, бит_ПлатежныеДокументыГИСЖКХ.Ссылка КАК ДокОплаты, МЕСЯЦ(бит_ПлатежныеДокументыГИСЖКХ.РасчетныйПериод) КАК МеясцРасчетныйПериод, ГОД(бит_ПлатежныеДокументыГИСЖКХ.РасчетныйПериод) КАК ГодРасчетныйПериод, бит_ПлатежныеДокументыГИСЖКХ.ИдентификаторПД КАК ИдентификаторПД ПОМЕСТИТЬ ВТ_ДокОплаты ИЗ Справочник.бит_ПлатежныеДокументыГИСЖКХ КАК бит_ПлатежныеДокументыГИСЖКХ ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_ЛицевыеСчета КАК бит_ЛицевыеСчета ПО бит_ПлатежныеДокументыГИСЖКХ.ЛицевойСчет = бит_ЛицевыеСчета.Ссылка ГДЕ МЕСЯЦ(бит_ПлатежныеДокументыГИСЖКХ.РасчетныйПериод) = МЕСЯЦ(&Период) И ГОД(бит_ПлатежныеДокументыГИСЖКХ.РасчетныйПериод) = ГОД(&Период) И бит_ПлатежныеДокументыГИСЖКХ.ЭтоГруппа = ЛОЖЬ ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ //ПРЕДСТАВЛЕНИЕ(бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор) КАК ИдентификаторПД, бит_НачисленияПоУслугамЖКХПоПериоду.ЛицевойСчет КАК ЛицевойСчет, СУММА(бит_НачисленияПоУслугамЖКХПоПериоду.Сумма) КАК Сумма, бит_НачисленияПоУслугамЖКХПоПериоду.Период КАК Период, бит_НачисленияПоУслугамЖКХПоПериоду.ЛицевойСчет.ИдентификаторЖКУ КАК ИдентификаторЖКУ, бит_НачисленияПоУслугамЖКХПоПериоду.ПериодВзаиморасчетов КАК ПериодВзаиморасчетов, бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор.Дата КАК ДатаВнесения, // ВТ_ДокОплаты.ДокОплаты КАК ДокОплаты, // ВТ_ДокОплаты.ЛицевойСчет КАК ЛицевойСчетДокОплаты, ВТ_ДокОплаты.ИдентификаторПД КАК ИдентификаторПД ИЗ ВТ_ДокОплаты КАК ВТ_ДокОплаты ПРАВОЕ СОЕДИНЕНИЕ РегистрНакопления.бит_НачисленияПоУслугамЖКХПоПериоду КАК бит_НачисленияПоУслугамЖКХПоПериоду ПО ВТ_ДокОплаты.ЛицевойСчет = бит_НачисленияПоУслугамЖКХПоПериоду.ЛицевойСчет ГДЕ (ТИПЗНАЧЕНИЯ(бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор) = ТИП(Документ.бит_ОплатаКУ) ИЛИ ТИПЗНАЧЕНИЯ(бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор) = ТИП(Документ.бит_РаспределениеАванса)) И МЕСЯЦ(бит_НачисленияПоУслугамЖКХПоПериоду.Период) = МЕСЯЦ(&Период) И ГОД(бит_НачисленияПоУслугамЖКХПоПериоду.Период) = ГОД(&Период) И бит_НачисленияПоУслугамЖКХПоПериоду.ПериодВзаиморасчетов <> ДАТАВРЕМЯ(1,1,1,0,0,0) и Сумма > 0
СГРУППИРОВАТЬ ПО бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор, бит_НачисленияПоУслугамЖКХПоПериоду.ЛицевойСчет, бит_НачисленияПоУслугамЖКХПоПериоду.ПериодВзаиморасчетов, бит_НачисленияПоУслугамЖКХПоПериоду.Период, бит_НачисленияПоУслугамЖКХПоПериоду.ЛицевойСчет.ИдентификаторЖКУ, // ВТ_ДокОплаты.ДокОплаты, // ВТ_ДокОплаты.ЛицевойСчет, ВТ_ДокОплаты.ИдентификаторПД, бит_НачисленияПоУслугамЖКХПоПериоду.Регистратор.Дата
